/** Same deep continuation certificate: old transfer refuses, explicit session succeeds at unchanged bound. */
public final class ContextUniversalCertifiedTransferBudgetRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    public static void main(String[] args){try {
        System.setProperty("user.home",java.nio.file.Files.createTempDirectory("certified-transfer-budget-").toString());Snapshot x=ContextUniversalGroupedRoundsRunner.bind(true,"!anchor(1); !@u p(u);"),a=ContextUniversalGroupedRoundsRunner.bind(false,"!@u (p(u)&&b(u)->r(u))&&(p(u)&&r(u)->s(u));"),b=ContextUniversalGroupedRoundsRunner.bind(false,"!b(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> supplied=Arrays.asList(a,b);ContextUniversalCompoundExchange.Exchange input=ContextUniversalGroupedRoundsRunner.exchange(x,supplied,p,Collections.emptyMap());ContextUniversalGroupedRounds.SessionRun run=ContextUniversalGroupedRounds.runWithValidationReuse(x,supplied,p,Collections.emptyMap(),ContextUniversalGroupedRoundsRunner.units(input),input,ContextUniversalGroupedRoundsRunner.limits(16),ContextUniversalGroupedRoundsRunner.local(),8,WORK,4096);ContextUniversalGroupedRounds.Result stable=run.result;require(stable.status==ContextUniversalGroupedRounds.Status.STABLE_GROUPED_POOLS&&stable.completedRounds==3,stable.phase+": "+stable.reason);
        ContextUniversalFrozenConstraints.Result base=ContextUniversalFrozenConstraints.closeSignedCompounds(ContextUniversalCompoundExchangeRunner.rows(x,null),stable.output.packet,null,stable.symbolicOutput,stable.compoundOutput,16,16,512,256,WORK);require(base.closed,base.reason);ContextUniversalGroupedLocalRounds.Closure local=ContextUniversalGroupedLocalRounds.runWithValidationReuse(base,ContextUniversalGroupedRoundsRunner.local(),4096);require(local.stable,local.reason);
        ConstraintTransfer old=ContextWitnessResultTransport.transferConstraintsCertified(local.output,16,WORK);require(!old.transferred&&old.output==null&&old.local==null&&old.privateAfter==null&&old.bindings==null&&old.certificate==null&&old.reason.contains("Witness transport work limit"),"retained actual legacy transfer refusal at64m: "+old.reason);
        SessionTransfer fresh=ContextWitnessResultTransport.transferConstraintsCertifiedWithValidationReuse(local.output,16,WORK,4096);require(fresh.transfer.transferred&&fresh.metrics.work<WORK&&fresh.metrics.hits>0&&fresh.metrics.entries==0,fresh.transfer.reason);require(fresh.transfer.proof==local.output.output&&fresh.transfer.certificate==local.output&&fresh.transfer.bindings.coverage==local.output.output,"same ACTUAL large certificate and proof owner");require(ContextWitnessResultTransport.sameContents(fresh.transfer.output,stable.output.packet,WORK)&&ContextWitnessResultTransport.sameContents(fresh.transfer.local,stable.output.packet,WORK)&&!fresh.transfer.commonChanged&&!fresh.transfer.localChanged,"unchanged exact fixed minima/input retention on resumed self-X cut");require(fresh.transfer.output.basis==null&&!fresh.transfer.output.observedStep&&fresh.transfer.output.coveredCut==null,"no inherited admission/STEP marker");
        ContextUniversalSignedProductAudit.Result audit=ContextUniversalSignedProductAudit.bind(local.output.output,fresh.transfer,65536,WORK);require(!audit.bound&&audit.products.isEmpty()&&audit.reason.contains("Ground transport work limit"),"remaining separate product-audit budget is preserved as refusal: "+audit.reason);
        System.out.println("CERTIFIED_TRANSFER_RETAINED legacyRefused=true sessionWork="+fresh.metrics.work+" hits="+fresh.metrics.hits+" verified="+fresh.metrics.verified+" peak="+fresh.metrics.peakEntries+" auditBound="+audit.bound);
        System.out.println("CONTEXT_UNIVERSAL_CERTIFIED_TRANSFER_BUDGET_PASS checks="+checks);System.exit(0);
    }catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
